50	export async function readAll(db: StateFirstDB, request: PagedRead, limit?: number): Promise<AnyDoc[]> {
51	  const out: AnyDoc[] = [];
52	  for await (const page of queryPages(db, request, limit !== undefined ? Math.min(limit, PAGE_LIMIT) : PAGE_LIMIT)) {
53	    for (const record of page) {
54	      if (limit !== undefined && out.length >= limit) return out;
