62	/** How many records match, counted page by page; no page is kept. */
63	export async function countAll(db: StateFirstDB, request: PagedRead): Promise<number> {
64	  let n = 0;
65	  for await (const page of queryPages(db, request)) n += page.length;
66	  return n;
