{"path":"packages/appboundry-host/test/admin-many-sessions.test.ts","content":"/**
 * Admin reads of host collections past FeltDB's 1,000-match unpaged find() limit.
 * Every issued session is a record in the sessions collection; admin.ts reads them with an unpaged find({}).
 */
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { ArtifactHost, loadArtifact, localActor } from "@appport/appboundry-host";
import { syntheticArtifact, type SyntheticFunction } from "./helpers.js";

let work: string;
beforeEach(async () => { work = await mkdtemp(join(tmpdir(), "appboundry-sessions-")); });
afterEach(async () => { await rm(work, { recursive: true, force: true }); });

const FUNCTIONS: SyntheticFunction[] = [
  { name: "items:count", kind: "query", access: "data.read", body: `async (a, host) => host("db.count", { collection: "items", filter: {} })` }
];

const N = 1_005;

describe("admin with more than 1,000 sessions", () => {
  it("still lists and revokes a user's sessions", async () => {
    const artifact = await syntheticArtifact(work, FUNCTIONS, "many", { roles: { member: ["data.*"] } });
    const host = await ArtifactHost.open({ artifact: await loadArtifact(artifact), stateDir: join(work, "state"), environment: "production", jobIntervalMs: 0 });
    try {
      await host.admin(a => a.bootstrap(localActor(), { operator: "ops" }));
      await host.admin(a => a.addUser({ kind: "operator", id: "ops" }, { id: "ada", roles: ["member"] }));
      for (let i = 0; i < N; i++) await host.admin(a => a.issueSession({ kind: "operator", id: "ops" }, { user: "ada" }));
      let listed: unknown;
      try { listed = (await host.admin(a => a.listSessions({ user: "ada" }))).length; } catch (error) { listed = `threw ${(error as { code?: string }).code ?? ""} ${(error as Error).message}`; }
      expect(listed).toBe(N);
      let revoked: unknown;
      try { revoked = (await host.admin(a => a.revokeSessions({ kind: "operator", id: "ops" }, { user: "ada" }))).revoked; } catch (error) { revoked = `threw ${(error as { code?: string }).code ?? ""} ${(error as Error).message}`; }
      expect(revoked).toBe(N);
    } finally { await host.close(); }
  }, 600_000);
});
"}

